from __future__ import annotations

import importlib


def load_config(text: str) -> dict:
    """Load a maintainer-authored local profile string.

    Profile values are Python expressions.  The profiles are versioned with this
    project and are not user/network supplied, so they are evaluated directly to
    support the expression features documented in README.md.
    """
    settings = {}
    plugin_name = None

    # Use one namespace for globals and locals so comprehensions and later lines
    # can see normal builtins plus any settings evaluated earlier in the file.
    namespace = dict(settings)

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"invalid config line {lineno}: missing '='")

        key, expr = line.split("=", 1)
        key = key.strip()
        expr = expr.strip()
        if not key:
            raise ValueError(f"invalid config line {lineno}: empty key")

        value = eval(expr, namespace, namespace)
        if key == "plugin":
            plugin_name = value
        else:
            settings[key] = value
            namespace[key] = value

    plugin = None
    if plugin_name is not None:
        module = importlib.import_module(plugin_name)
        plugin = module.Transform()

    return {"settings": settings, "plugin": plugin}
"}
